function leftoverCrates(crates: number[], bins: number[]): number {
  const n = bins.length;
  let size = 1;
  while (size < n) size *= 2;
  const tree = new Array(2 * size).fill(0);
  for (let j = 0; j < n; j++) tree[size + j] = bins[j];
  for (let v = size - 1; v >= 1; v--) tree[v] = Math.max(tree[2 * v], tree[2 * v + 1]);
  let left = 0;
  for (const c of crates) {
    if (tree[1] < c) { left++; continue; }
    let v = 1;
    while (v < size) v = tree[2 * v] >= c ? 2 * v : 2 * v + 1; // prefer the left half
    tree[v] = 0; // bin is now used
    for (v >>= 1; v >= 1; v >>= 1) tree[v] = Math.max(tree[2 * v], tree[2 * v + 1]);
  }
  return left;
}

