                left += 1
                continue
            v = 1
            while v < size:
                v = 2 * v if tree[2 * v] >= c else 2 * v + 1
            tree[v] = 0
            v //= 2
            while v:
                tree[v] = max(tree[2 * v], tree[2 * v + 1])
